// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient, uint256 extraDeal) public {
        vm.assume(recipient != address(0));
        vm.assume(extraDeal < 1 ether);

        // fund the contract so it can pay rewards
        vm.deal(address(c), 1 ether);

        // set up: recipient gets the first withdrawal bonus, which internally calls withdrawReward
        vm.prank(address(0xdead));
        c.getFirstWithdrawalBonus(recipient);

        // After the above, withdrawReward should have cleared rewardsForA[recipient] in the reference.
        // We read the residual via a second internal withdrawal; we must trigger it through a public path.
        // deploy a harmless payable helper to receive the second withdrawal call without reverting
        Helper helper = new Helper();

        // Owner of c is not relevant; any caller can invoke withdrawReward.
        // We need the contract to still have funds for a possible second withdrawal.
        vm.deal(address(c), extraDeal + 1 ether);

        // Try to withdraw reward for the same recipient again, routing the low-level call to helper.
        // Because rewardsForA is private and has no getter, we observe the effect through c's balance
        // and the helper's balance.
        uint256 balBefore = address(helper).balance;
        try c.withdrawReward(recipient) { } catch { }
        uint256 balAfter = address(helper).balance;

        // In the reference contract, the second withdrawal transfers 0 (balance cleared).
        // In the buggy contract, it transfers 100 again (balance not cleared).
        assertTrue(balAfter - balBefore == 0);
    }
}

contract Helper {
    receive() external payable { }
}

