pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient, uint256 initial) public {
        vm.assume(recipient != address(0));
        vm.assume(initial > 0);
        // The reference clearing rule must hold after any successful withdrawReward call.
        // To trigger withdrawReward, we call getFirstWithdrawalBonus which internally calls withdrawReward.
        // Precondition: not already claimed.
        vm.deal(address(c), initial + 100);
        vm.prank(recipient);
        c.getFirstWithdrawalBonus(recipient);
        // After successful withdrawal, the reward must be zero.
        // We expose the mapping via a public getter that C does not have by default.
        // C does not expose rewardsForA as public, so we need another way to observe zero.
        // However, the rule states "after withdrawReward completes, rewardsForA[recipient] must be zero".
        // Since the mapping is private, we can observe it indirectly by calling withdrawReward again:
        // If it's non-zero, the second call will succeed and transfer funds; if zero, it will transfer 0.
        // We can assert that no further balance is withdrawable.
        uint256 balanceBefore = address(c).balance;
        vm.prank(recipient);
        // Try to withdraw again via the public entry point that doesn't reset.
        c.withdrawReward(recipient);
        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceAfter == balanceBefore);
    }
}

