pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient, uint8 bonusCalls) public {
        vm.assume(recipient != address(0) && recipient != address(c));
        vm.deal(address(c), 1000 ether);
        // give the recipient some bonus via getFirstWithdrawalBonus
        vm.prank(recipient);
        c.getFirstWithdrawalBonus(recipient);
        // Additional calls to increase rewards – up to 255 times
        for (uint8 i = 0; i < bonusCalls; i++) {
            vm.prank(recipient);
            try c.getFirstWithdrawalBonus(recipient) {} catch {}
        }
        // Now check invariant: after any subsequent withdrawReward call,
        // the stored reward for recipient must be zero.
        vm.prank(recipient);
        c.withdrawReward(recipient);
        // The mapping is private; we can only observe it externally through the effect.
        // A second withdraw should fail if rewardForA is zero, because amountToWithdraw=0 and no value sent.
        // But with the bug, rewardForA stays non-zero, so second withdraw succeeds.
        bool secondCallSucceeded;
        vm.prank(recipient);
        try c.withdrawReward(recipient) { secondCallSucceeded = true; } catch { secondCallSucceeded = false; }
        // For the correct contract, the second call must fail (no value to send, call with 0 value still succeeds, but require(success) is true if call to recipient with 0 value succeeds? Actually low-level call with 0 wei to EOA always succeeds. So we cannot rely on revert.
        // Instead, we check balance: recipient balance after two withdrawals must equal only one bonus amount if correct, but double if buggy.
        // But we don't hardcode amounts. So we check contract's balance did not lose more than it should.
        // Alternative: Reliable observable: correct contract clears reward, so a third party able to call withdrawReward on behalf of recipient would also see 0 effect. But that's not a single assertion on c.
        // We can deploy a helper that records the call value and reverts on second call.
        // Since the mapping is private, the only public surface is the contract's behavior through low-level call.
        // Use a helper that tracks received value.
        // But rule: single assertTrue on c's public surface. 
        // We can assert address(c).balance == initialBalance - 100 after first withdrawal? Not general.
        // We need a property: after a successful withdrawReward(recipient) by the recipient, a subsequent attempt to withdraw ANYTHING for that recipient must not cause the contract to send more Ether. Can check contract balance decrease.
        // Or: after withdrawReward, any further attempt to withdraw MUST revert (not enough value) or send 0. But sent 0 is possible.
        // Because rewardsForA is private, we cannot read it. The only external effect is the call to recipient. We can observe recipient's balance change. 
        // To keep invariant general, we record recipient's balance before and after two withdrawals, and assert that the total received equals at most the initial reward amount (which is unknown but can be inferred from first withdrawal).
        // However, the assertion must be on c's public surface. "address(c).balance" is public surface.
        // The correct contract's invariant: sum of all withdrawable rewards equals initial sum minus paid-out. But we can check: a second withdrawal does not transfer any Ether.
        // Since we cannot read the mapping, we can observe that a second call to withdrawReward does not emit an event (none) or change c's balance.
        uint256 balanceBeforeSecond = address(c).balance;
        vm.prank(recipient);
        try c.withdrawReward(recipient) {} catch {}
        uint256 balanceAfterSecond = address(c).balance;
        assertTrue(balanceBeforeSecond == balanceAfterSecond);
        // For correct contract, rewardsForA[recipient] is zero, so amountToWithdraw = 0, call{value:0} sends 0, balance unchanged. Buggy contract leaves reward, so second call withdraws again, decreasing balance.
    }
}

