pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address recipient, uint8 depth) public {
        // Bound depth to prevent infinite loop; keep domain wide enough to trigger reentrancy.
        vm.assume(depth >= 1 && depth <= 10);
        // Ensure recipient is not the C contract itself and not a precompile. We rely on the fuzzer to supply an EOA;
        // to make the adversarial reentrant caller we must deploy a helper and use its address.
        // The bug only manifests when callee is a reentrant attacker; we MUST deploy it per ADVERSARIAL COUNTERPARTY rule.
        vm.assume(recipient != address(c));
        vm.assume(recipient != address(0));
        vm.assume(recipient != address(this));
        vm.assume(uint160(recipient) > 10);

        // Deploy attacker that will reenter on withdraw
        ReentrantAttacker attacker = new ReentrantAttacker(address(c), depth);
        address attackerAddr = address(attacker);

        // We must give attacker some ether for the reentrant calls to succeed (withdrawReward does low-level call{value})
        // The original with first bonus gives 100 wei, and the attacker will withdraw that repeatedly.
        uint256 required = 100 * uint256(depth) + 100;
        vm.deal(address(c), required); // fund C so it can pay out

        // Record initial balances
        uint256 balanceCBefore = address(c).balance;

        // Prank the attacker to call getFirstWithdrawalBonus
        vm.prank(attackerAddr);
        c.getFirstWithdrawalBonus(attackerAddr);

        // The invariant: After all calls finished, the contract's balance plus total paid out (held by attacker) should be exactly
        // the initial balance plus total bonuses (which is 100 * passes). Because the correct nonReentrant prevents reentrancy,
        // only one bonus (100) is ever given and withdrawn. The bug permits multiple bonuses via reentrancy, making the sum
        // exceed initial balance + 100.
        uint256 balanceCAfter = address(c).balance;
        uint256 attackerBalance = address(attacker).balance;
        // Total bonuses given: in correct version, exactly 100 (one call). Bug gives more.
        // Since attacker holds withdrawn rewards, we can assert: balanceCAfter + attackerBalance == balanceCBefore + 100 * 1 (correct).
        // To make it a property that fails on bug: the bug gives 100 * depth, so sum > balanceCBefore + 100.
        // The invariant is: balanceCAfter + attackerBalance <= balanceCBefore + 100.
        // But in the correct contract it's always ==, so <= holds. In bug, it's >.
        assertTrue(balanceCAfter + attackerBalance <= balanceCBefore + 100);
    }
}

contract ReentrantAttacker {
    C public target;
    uint256 public depth;
    uint256 public count;

    constructor(address _target, uint256 _depth) {
        target = C(_target);
        depth = _depth;
        count = 0;
    }

    fallback() external payable {
        if (count < depth) {
            count++;
            target.withdrawReward(address(this));
        }
    }

    receive() external payable {
        if (count < depth) {
            count++;
            target.withdrawReward(address(this));
        }
    }
}

