pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address recipient, uint8 bonusCount) public {
        // Bound bonusCount to avoid overflow in setup, but keep it high enough for reentrancy to matter
        vm.assume(recipient != address(0) && recipient != address(c) && recipient.code.length == 0);
        bonusCount = uint8(bound(uint256(bonusCount), 1, 50));

        // Deploy an adversarial reentrant attacker that calls getFirstWithdrawalBonus again
        ReentrantAttacker attacker = new ReentrantAttacker(address(c));
        address attackerAddr = address(attacker);

        // Give the main contract enough ether to cover multiple bonuses
        uint256 initialBalance = uint256(bonusCount) * 100 ether;
        vm.deal(address(c), initialBalance);

        // Record initial contract balance
        uint256 balanceBefore = address(c).balance;

        // Start attack: recipient = attacker's address, attacker will reenter
        vm.prank(attackerAddr);
        try c.getFirstWithdrawalBonus(attackerAddr) { } catch { }

        // After the transaction, the contract's balance should be exactly decreased by the total bonuses paid
        // total bonuses = bonusCount * 100 (since each reentrant call grants 100)
        // The correct contract locks and prevents any reentrancy, so only one bonus is granted.
        // The buggy mutant allows bonusCount reentrant calls, granting more than intended.
        uint256 balanceAfter = address(c).balance;
        uint256 totalGrantable = uint256(bonusCount) * 100 ether;

        // In the reference, reentrancy is impossible, so only 100 ether is paid.
        // In the buggy, up to bonusCount * 100 ether is paid, reducing the balance drastically.
        // The invariant: contract balance never drops below initial balance minus total bonuses that could POSSIBLY be granted in a single transaction (100 ether).
        // If more than 100 ether is drained, it's a bug.
        assertTrue(balanceAfter >= balanceBefore - totalGrantable);
    }
}

contract ReentrantAttacker {
    C target;
    uint8 count;
    uint8 maxCount;
    constructor(address _target) {
        target = C(_target);
        maxCount = 50; // will be set by the caller via reentrancy depth
    }
    fallback() external payable {
        if (count < maxCount) {
            count++;
            target.getFirstWithdrawalBonus(address(this));
        }
    }
    receive() external payable {
        if (count < maxCount) {
            count++;
            target.getFirstWithdrawalBonus(address(this));
        }
    }
}

