        c.getFirstWithdrawalBonus(recipient);
        totalBonuses += 100;

        // Attempt a second call; correct reverts because claimedBonus[recipient] is true
        (bool ok,) = address(c).call(abi.encodeWithSignature("getFirstWithdrawalBonus(address)", recipient));

        uint balanceAfter = address(c).balance;
