pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address recipient, uint256 extraCalls) public {
        vm.assume(recipient != address(0) && recipient != address(c));
        extraCalls = bound(extraCalls, 0, 5);

        // Deploy a re-entrant attacker that calls withdrawReward again on receive.
        ReentrantAttacker attacker = new ReentrantAttacker(c);
        address attackerAddr = address(attacker);

        // Fund attacker so it can receive and later be checked – we only need it to call c.
        vm.deal(attackerAddr, 0);

        // Record initial balances.
        uint256 initialContractBalance = address(c).balance;
        uint256 initialRewardsForAttacker = c.rewardsForA(attackerAddr);
        uint256 initialRewardsRecipient = c.rewardsForA(recipient);

        // Attacker receives bonus and triggers reentrancy via withdrawReward.
        vm.prank(attackerAddr);
        try c.getFirstWithdrawalBonus() {
            // on success, attacker may have reentered
        } catch {}

        uint256 finalContractBalance = address(c).balance;
        uint256 finalRewardsForAttacker = c.rewardsForA(attackerAddr);
        uint256 finalRewardsRecipient = c.rewardsForA(recipient);

        // For any recipient chosen by fuzzer, rewardsForA[recipient] should be unchanged
        // (attacker is the only actor).
        // The invariant: sum of contract balance + sum of all rewardsForA of all users touched
        // equals initial sum + 100. Here we only know attacker received the bonus.
        // However, since recipient is fuzzed and not interacted with, its rewardsForA should remain unchanged.
        // The universal property: the attacker cannot drain more than the single 100 bonus.
        // So final contract balance + final rewardsForAttacker + final rewardsRecipient
        // must equal initialContractBalance + initialRewardsForAttacker + initialRewardsRecipient + 100.
        assertTrue(
            finalContractBalance + finalRewardsForAttacker + finalRewardsRecipient
            == initialContractBalance + initialRewardsForAttacker + initialRewardsRecipient + 100
        );
    }
}

